import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.zip.*;
/** Compares every packaged public asset with the exact source bytes, without extracting the APK. */
public final class VerifyApkAssets {
 private static byte[] hash(InputStream input)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");byte[] buffer=new byte[65536];int count;while((count=input.read(buffer))!=-1)digest.update(buffer,0,count);return digest.digest();}
 public static void main(String[] args)throws Exception{Path source=Paths.get(args[1]).toAbsolutePath().normalize();int count=0;Set<String> found=new HashSet<>();try(ZipFile zip=new ZipFile(args[0])){Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){ZipEntry entry=entries.nextElement();if(entry.isDirectory()||!entry.getName().startsWith("assets/"))continue;String relative=entry.getName().substring(7);Path file=source.resolve(relative).normalize();if(!file.startsWith(source)||!Files.isRegularFile(file))throw new AssertionError("Unexpected packaged asset: "+relative);try(InputStream packed=zip.getInputStream(entry);InputStream local=Files.newInputStream(file)){if(!Arrays.equals(hash(packed),hash(local)))throw new AssertionError("Stale packaged asset: "+relative);}found.add(relative.replace('\\','/'));count++;}if(args.length>2)try(ZipFile tested=new ZipFile(args[2])){for(String name:new String[]{"classes.dex","AndroidManifest.xml","resources.arsc"}){try(InputStream current=zip.getInputStream(zip.getEntry(name));InputStream previous=tested.getInputStream(tested.getEntry(name))){if(!Arrays.equals(hash(current),hash(previous)))throw new AssertionError("Native payload changed since emulator checks: "+name);}}System.out.println("PASS: native DEX, manifest and resources match the emulator-tested build.");}}try(java.util.stream.Stream<Path> stream=Files.walk(source)){for(Path file:(Iterable<Path>)stream.filter(Files::isRegularFile)::iterator){String relative=source.relativize(file).toString().replace('\\','/');if(!found.contains(relative))throw new AssertionError("Missing packaged asset: "+relative);}}System.out.println("PASS: all "+count+" packaged assets match source bytes.");}
}
